#pragma once
#include <cstdlib>
#include <string>

// Resolves a path relative to the synthetic test-data corpus this repository publishes at
// testdata/ (generated by tools/gen_world.py, already checked in so a clone builds and runs
// with no extra step -- run gen_world.py again to regenerate it, from a different seed if you
// like). AMS2_TESTDATA lets a caller point the harness at a different corpus instead.
#define TESTDATA(rel) \
    (std::string(std::getenv("AMS2_TESTDATA") ? std::getenv("AMS2_TESTDATA") : "testdata") + "/" + (rel)).c_str()
